export function createMemoryEventStore(seed={}) { const events=new Map((seed.events??[]).map(e=>[e.id,structuredClone(e)])); return { events:{ async get(id){return structuredClone(events.get(id)??null)}, async getBySlug(slug){return structuredClone([...events.values()].find(e=>e.publicSlug===slug)??null)}, async list(){return structuredClone([...events.values()])}, async create(e){events.set(e.id,structuredClone(e));return structuredClone(e)}, async update(id,e){events.set(id,structuredClone(e));return structuredClone(e)} } }; }
